import React, { useContext } from 'react';
import { UserContext } from '../context/UserContext';
import axios from 'axios';

const DeleteUser = ({ userId }) => {
    const { setUsuarios } = useContext(UserContext);  // Asumiendo que tienes un estado para la lista de usuarios

    const handleDelete = async () => {
        if (window.confirm("¿Estás seguro de que deseas eliminar este usuario?")) {
            try {
                // Enviar solicitud DELETE al servidor
                const response = await axios.delete('http://localhost/SERVIDOR/practica/api.php', {
                    data: { id: userId }  // Pasar el ID del usuario en el cuerpo de la solicitud
                });

                if (response.data.success) {
                    // Actualizar el estado de usuarios después de la eliminación
                    setUsuarios(prevUsuarios => prevUsuarios.filter(usuario => usuario.id_usu !== userId));
                    alert("Usuario eliminado con éxito");
                } else {
                    alert("Error al eliminar el usuario");
                }
            } catch (error) {
                console.error('Error al eliminar el usuario:', error);
                alert("Error al eliminar el usuario");
            }
        }
    };

    return (
        <button onClick={handleDelete} style={{ color: 'red' }}>
            Eliminar
        </button>
    );
};

export default DeleteUser;
